-- Groups of people: each has a name and belongs to one sheet (null for the unnamed sheet), numbered
-- within it like people. "group" is a reserved word, so the table is person_group.
CREATE TABLE person_group (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(255) REFERENCES sheet (id) ON DELETE CASCADE,
    local_id BIGINT NOT NULL,
    name VARCHAR(255) NOT NULL,
    sheet_key VARCHAR(255) GENERATED ALWAYS AS (COALESCE(sheet_id, ''))
);
CREATE UNIQUE INDEX person_group_sheet_local_id ON person_group (sheet_key, local_id);
-- A person is in one group; absent until put in one.
ALTER TABLE person ADD COLUMN group_id BIGINT REFERENCES person_group (id) ON DELETE SET NULL;
-- A person may be in any number of groups of their sheet, not just one.
CREATE TABLE person_membership (
    person_id BIGINT NOT NULL REFERENCES person (id) ON DELETE CASCADE,
    group_id BIGINT NOT NULL REFERENCES person_group (id) ON DELETE CASCADE,
    PRIMARY KEY (person_id, group_id)
);
INSERT INTO person_membership (person_id, group_id) SELECT id, group_id FROM person WHERE group_id IS NOT NULL;
ALTER TABLE person DROP COLUMN group_id;
package net.officefloor.hq.app.people;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/** A named group of people on one sheet (null for the unnamed sheet), numbered within it. A person may be in any number of groups. */
@Entity
@Table(name = "person_group")
public class PersonGroup {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    /** The group's id within its sheet; the id the user and the API see. */
    @Column(name = "local_id")
    private Long localId;

    /** The id of the sheet the group belongs to; null for the unnamed sheet. */
    @Column(name = "sheet_id")
    private String sheetId;

    private String name;

    protected PersonGroup() {
    }

    public PersonGroup(String sheetId, long localId, String name) {
        this.sheetId = sheetId;
        this.localId = localId;
        this.name = name;
    }

    public Long getId() {
        return id;
    }

    public Long getLocalId() {
        return localId;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }
}
package net.officefloor.hq.app.people;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import java.util.List;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/groups")
public class GroupController {

    /** A group: its id on its sheet and its name. */
    public record GroupView(Long id, String name) {
        static GroupView of(PersonGroup g) {
            return new GroupView(g.getLocalId(), g.getName());
        }
    }

    public record NewGroup(@NotBlank String name) {
    }

    private final PersonService service;

    public GroupController(PersonService service) {
        this.service = service;
    }

    /** The groups on the request's sheet; blank or absent means the unnamed sheet. */
    @GetMapping
    public List<GroupView> list(@RequestParam(required = false) String sheet) {
        return service.groups(sheetId(sheet)).stream().map(GroupView::of).toList();
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public GroupView add(@RequestParam(required = false) String sheet, @Valid @RequestBody NewGroup group) {
        return GroupView.of(service.addGroup(sheetId(sheet), group.name()));
    }

    private static String sheetId(String sheet) {
        return sheet == null || sheet.isBlank() ? null : sheet.trim();
    }
}
package net.officefloor.hq.app.people;

import java.util.List;
